'use strict';
const $=id=>document.getElementById(id), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), num=(x,n=1)=>x==null?'—':Number(x).toFixed(n), pct=x=>x==null?'—':(100*x).toFixed(1)+'%', grade=x=>({primary:'一级道路',secondary:'二级道路',tertiary:'三级道路'}[x]||x), fmt=x=>Number(x).toLocaleString('zh-CN');
let D,roads,byId,filtered=[],selected,compared=[],roadPage=0,photoPage=0,zoom=1,pan=[0,0],activeTab='map',predictionRows=[],predictionPage=0;
const metric=()=>$('mapMetric').value;
const scoreColor=v=>v==null?'#c2ccc0':v<25?'#d6c59e':v<50?'#a8bb7d':v<75?'#719b66':'#2d654b';
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',2300)}
function modal(html){$('modalBody').innerHTML=html;$('modal').showModal()}
function kpis(){const v=filtered.filter(r=>r.visual_subindex!=null).length,c=filtered.filter(r=>r.environment_index!=null).length;const photos=filtered.reduce((s,r)=>s+(r.image_count||0),0);$('kpis').innerHTML=[[fmt(filtered.length),'当前道路记录','全部 '+fmt(D.meta.roads)+' 条道路','◈'],[fmt(photos),'关联街景图片','原始索引中实际存在的图片','▧'],[v,'视觉子指数可用','绿化 + 低可见车辆','↗'],[c,'完整代理指数可用','视觉 + 低标注限速','⌁']].map(([v,l,s,i])=>`<div class="kpi"><div class="kpi-label">${l}<i>${i}</i></div><strong>${v}</strong><small>${s}</small></div>`).join('')}
function applyFilters(){const q=$('search').value.trim().toLowerCase(),region=$('region').value,g=$('grade').value,s=$('structure').value;filtered=roads.filter(r=>(!q||(r.name||'').toLowerCase().includes(q)||r.road_id.toLowerCase().includes(q))&&(!region||r.region_group===region)&&(!g||r.fclass===g)&&(!s||r.structure_group===s));roadPage=0;kpis();renderList();renderMap()}
function selectRoad(id,navigate=true){if(!byId.has(id))return;selected=id;photoPage=0;renderList();renderDetail();if(navigate)location.hash='detail';else{renderMap();toast('已选择道路，可打开街道详情')}}
function addCompare(id){if(compared.includes(id))return toast('这条道路已在对比中');if(compared.length===4)return toast('一次最多对比 4 条道路');compared.push(id);renderCompare();toast('已加入指标对比')}
function renderList(){const list=filtered.slice(roadPage*20,(roadPage+1)*20);$('resultCount').textContent=fmt(filtered.length);$('roadList').innerHTML=list.length?list.map(r=>`<div class="roadrow ${r.road_id===selected?'selected':''}"><button class="text-button roadrow-main" data-road="${r.road_id}" style="text-align:left;padding:0"><b>${esc(r.name||r.road_id)}</b><small>${esc(r.region_group)} · ${grade(r.fclass)} · ${esc(r.structure_group)}</small></button><span class="roadrow-score">${num(r[metric()],0)}</span><button class="addsmall" data-add="${r.road_id}" aria-label="加入对比 ${esc(r.name||r.road_id)}">＋</button></div>`).join(''):'<div class="empty">没有符合筛选条件的道路。<br>请调整筛选条件。</div>';$('roadPage').textContent=`${filtered.length?roadPage+1:0} / ${Math.ceil(filtered.length/20)}`;$('prevRoads').disabled=roadPage===0;$('nextRoads').disabled=(roadPage+1)*20>=filtered.length}
const project=(lon,lat)=>[40+(lon-113.525)/.08*650,480-(lat-22.105)/.12*440];
function renderMap(){
 const container=$('map');let svg=container.querySelector('svg');
 if(!svg){
  const polygonPaths=[];
  for(const f of D.boundaries.features){const geometry=f.geometry,polys=geometry.type==='Polygon'?[geometry.coordinates]:geometry.coordinates;for(const polygon of polys)polygonPaths.push(`<path class="map-region" d="${polygon.map(ring=>ring.map(([x,y],i)=>`${i?'L':'M'}${project(x,y).join(' ')}`).join(' ')+' Z').join(' ')}"/>`)}
  container.innerHTML=`<svg viewBox="0 0 750 530" aria-label="道路采样代表位置地图"><rect width="750" height="530" fill="#edf2e9"/><g id="mapViewport">${polygonPaths.join('')}${[['澳门半岛',113.553,22.211],['氹仔',113.558,22.162],['路氹',113.578,22.141],['路环',113.563,22.116]].map(([label,lon,lat])=>{const xy=project(lon,lat);return `<text x="${xy[0]}" y="${xy[1]}" class="map-label">${label}</text>`}).join('')}<g id="mapPoints"></g><g id="mapFocus" aria-hidden="true" pointer-events="none"><circle class="focus-wash" r="11"/><circle class="focus-ring ring-one" r="7"/><circle class="focus-ring ring-two" r="7"/><circle class="focus-core" r="4"/></g></g><text x="28" y="30" fill="#819477" font-size="10">N ↑</text><text x="28" y="510" fill="#819477" font-size="10">澳门 MACAU · 地理边界示意，无道路中心线</text></svg><div id="mapTooltip" role="tooltip" hidden></div>`;
 }
 const points=filtered.filter(r=>r.longitude!=null&&r.latitude!=null),layer=$('mapPoints'),existing=new Map([...layer.querySelectorAll('[data-maproad]')].map(c=>[c.dataset.maproad,c]));
 let alive=0;
 for(const road of points){
  let circle=existing.get(road.road_id);
  if(!circle){circle=document.createElementNS('http://www.w3.org/2000/svg','circle');circle.setAttribute('tabindex','0');circle.setAttribute('data-maproad',road.road_id);circle.appendChild(document.createElementNS('http://www.w3.org/2000/svg','title'));layer.appendChild(circle)}
  existing.delete(road.road_id);const xy=project(road.longitude,road.latitude);circle.setAttribute('cx',xy[0]);circle.setAttribute('cy',xy[1]);circle.setAttribute('r',road.road_id===selected?'5':'3.3');circle.setAttribute('fill',scoreColor(road[metric()]));circle.classList.toggle('is-selected',road.road_id===selected);circle.classList.add('roadpoint');circle.classList.toggle('is-alive',road[metric()]!=null&&alive++<24);circle.style.animationDelay=`${-alive*.21}s`;circle.firstElementChild.textContent=`${road.name||road.road_id} · ${num(road[metric()])}`;
 }
 for(const node of existing.values())node.remove();
 setMapView(true);focusMapRoad(points.find(r=>r.road_id===selected));reveal(layer);
 $('mapTooltip').hidden=true;$('mapfoot').textContent=`已定位 ${fmt(points.length)} 条 / 当前 ${fmt(filtered.length)} 条 · 滚轮缩放、拖动平移，点击点查看道路`;
}
function setMapView(immediate=false){const viewport=$('mapViewport');if(!viewport)return;viewport.classList.toggle('is-dragging',immediate);viewport.style.transform=`translate(${pan[0]}px,${pan[1]}px) translate(375px,265px) scale(${zoom}) translate(-375px,-265px)`}
function focusMapRoad(road){const focus=$('mapFocus');if(!focus)return;focus.style.display=road?'':'none';if(road){const xy=project(road.longitude,road.latitude);focus.setAttribute('transform',`translate(${xy[0]} ${xy[1]})`)}}

function photoHTML(p){return `<div class="card photocard"><img loading="lazy" src="photos/${p.source_sha256}.jpg" alt="街景 ${p.image_id}" data-photo="${p.image_id}"><div class="photo-info"><b>${p.image_id}</b><small>绿化 ${pct(p.vegetation_share)} · 建筑 ${pct(p.building_share)} · 天空 ${pct(p.sky_share)}</small><small>可见机动车 ${p.motor_vehicle_count} · 可见人物 ${p.person_count}</small><span class="badge ${p.quality_status==='needs_review'?'amber':''}">${p.quality_status==='needs_review'?'有质量复核提示':'自动规则未触发'}</span></div></div>`}
function renderDetail(){const r=byId.get(selected);if(!r)return;const photos=D.photosByRoad.get(selected)||[],items=photos.slice(photoPage*9,(photoPage+1)*9);$('detail-page').innerHTML=`<div class="section-title"><div><span class="badge">${grade(r.fclass)}</span><span class="badge">${esc(r.structure_group)}</span><span class="badge">${esc(r.region_group)}</span></div><button class="button primary" data-add="${r.road_id}">＋ 加入指标对比</button></div><div class="details-top"><div class="card contentpad"><h2>${esc(r.name||'未命名道路')}</h2><p style="font-size:11px;margin-top:10px">${r.road_id} · OSM ${esc(r.osm_id)}</p><div class="info-grid">${[['标注限速',r.speed_valid==null?'未填报有效值':r.speed_valid+' km/h'],['道路结构',r.structure_group],['单向属性',({B:'双向',F:'正向单向',T:'反向单向'}[r.oneway]||r.oneway)],['关联图片',photos.length+' 张'],['绿化可用不同图片',r.n_green_usable+' 张'],['车辆可用不同图片',r.n_vehicle_usable+' 张']].map(([k,v])=>`<div><small>${k}</small><b>${esc(v)}</b></div>`).join('')}</div></div><div class="card contentpad"><h3>道路环境代理指标</h3><div class="measure"><div><small>视觉子指数</small><strong>${num(r.visual_subindex)}</strong></div><div><small>完整代理指数</small><strong>${num(r.environment_index)}</strong></div><div><small>质量提示图片占比</small><strong>${pct(r.flagged_image_share)}</strong></div></div><div class="note">分项标准分（0–100）</div>${[['绿化',r.green_score],['低可见车辆',r.vehicle_score],['低标注限速',r.speed_score]].map(([k,v])=>`<div class="compare-value"><span>${k}</span><b>${num(v)}</b></div><div class="scorebar"><i style="width:${v??0}%"></i></div>`).join('')}</div></div><div class="section-title"><h2>街景图像 <span class="badge">${photos.length} 张</span></h2><span class="note">展示用缩略图 · 点击查看图像与质量信息</span></div><div class="gallery">${items.map(photoHTML).join('')||'<div class="card empty">此道路暂无可展示的街景照片。</div>'}</div><div class="pager"><button id="prevPhotos" ${photoPage===0?'disabled':''}>上一页图片</button><span>${photos.length?photoPage+1:0} / ${Math.ceil(photos.length/9)}</span><button id="nextPhotos" ${(photoPage+1)*9>=photos.length?'disabled':''}>下一页图片</button></div><div class="note">街景中的车辆包含停放车辆，人物检测不等同行人数。质量标记为复核线索，不是识别准确率；空指数表示未满足该项计算条件。</div>`}
function renderCompare(){const chosen=compared.map(id=>byId.get(id));$('compare-page').innerHTML=`<div class="card contentpad"><div class="section-title" style="margin-top:0"><h2>选择道路并列比较</h2><span class="badge">${compared.length} / 4</span></div><div class="compare-search"><select id="compareSelect" aria-label="选择对比道路">${filtered.map(r=>`<option value="${r.road_id}">${esc(r.name||r.road_id)} · ${r.road_id}</option>`).join('')}</select><button class="button primary" id="compareAdd">＋ 加入</button><button class="button" id="compareSelected">加入当前道路</button></div><p class="note">沿用同一参考尺度的环境指标；视觉子指数和完整代理指数分别比较。</p></div><div class="compare-grid" style="grid-template-columns:repeat(${Math.min(4,Math.max(chosen.length,1))},minmax(0,1fr))">${chosen.map(r=>`<div class="card compare-item"><button class="remove" data-remove="${r.road_id}" style="float:right" aria-label="移除道路">×</button><h3>${esc(r.name||r.road_id)}</h3><p style="font-size:10px">${r.road_id} · ${grade(r.fclass)}</p>${[['视觉子指数',r.visual_subindex],['完整代理指数',r.environment_index],['绿化标准分',r.green_score],['低可见车辆标准分',r.vehicle_score],['低标注限速标准分',r.speed_score]].map(([k,v])=>`<div class="compare-value"><span>${k}</span><b>${num(v)}</b></div><div class="scorebar"><i style="width:${v??0}%"></i></div>`).join('')}<button class="text-button" data-road="${r.road_id}">打开道路详情 ↗</button></div>`).join('')||'<div class="card empty">从地图或上方列表加入道路，最多同时比较 4 条。</div>'}</div><div class="card tablewrap" style="margin-top:20px"><table><thead><tr><th>原始指标与样本</th>${chosen.map(r=>`<th>${esc(r.name||r.road_id)}</th>`).join('')}</tr></thead><tbody>${[['绿化比例中位数','green_median',pct],['可见机动车数中位数','vehicle_median',num],['标注限速 km/h','speed_valid',num],['可用绿化图片数','n_green_usable',x=>x],['可用车辆图片数','n_vehicle_usable',x=>x]].map(([label,key,formatter])=>`<tr><td>${label}</td>${chosen.map(r=>`<td>${formatter(r[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;if(innerWidth<760){document.querySelector('.compare-grid').style.gridTemplateColumns='1fr'}}
function calcMetrics(rows){if(!rows.length)return {MAE:null,RMSE:null,R2:null,n:0};const avg=rows.reduce((s,r)=>s+r.y_true,0)/rows.length,sse=rows.reduce((s,r)=>s+(r.y_true-r.y_pred)**2,0),sst=rows.reduce((s,r)=>s+(r.y_true-avg)**2,0);return {n:rows.length,MAE:rows.reduce((s,r)=>s+Math.abs(r.y_true-r.y_pred),0)/rows.length,RMSE:Math.sqrt(sse/rows.length),R2:sst?sse/sst*-1+1:null}}
function renderPredict(){if(!$('task')){$('predict-page').innerHTML=`<div class="card contentpad"><div class="controls"><label>预测目标<select id="task" aria-label="预测目标"><option value="visual_proxy">视觉环境代理目标</option><option value="complete_proxy">完整环境代理目标</option></select></label><label>输入特征<select id="feature" aria-label="输入特征"><option value="road_context">道路属性 + 视觉背景</option><option value="road_only">仅道路属性</option></select></label><label>模型<select id="model" aria-label="模型"><option value="MLP">多层感知机 MLP</option><option value="linear">线性回归</option><option value="random_forest">随机森林</option><option value="gradient_boosting">梯度提升</option><option value="mean">均值预测</option></select></label><label>数据集合<select id="split" aria-label="数据集合"><option value="test">测试集</option><option value="validation">验证集</option><option value="train">训练集</option></select></label></div><p class="note" style="padding-bottom:0">展示已完成的实验预测；MLP 使用预先固定的主种子 42。目标在训练集尺度下定义，与地图中的全样本标准化指数分别解释。此页不受地图区域筛选影响。</p></div><div class="chart-layout"><div class="card"><div class="cardhead"><h2>预测值与实验目标值</h2><span>虚线为理想预测</span></div><div id="predMetrics" class="metricstrip"></div><div id="scatter"></div></div><div class="card"><div class="cardhead"><h2>相同任务与特征集：模型对比</h2></div><div class="tablewrap" id="modelTable"></div><div class="note contentpad">测试分数不参与模型选择。完整目标测试集仅 7 条道路；代理目标仍需独立环境评价验证。</div></div></div><div class="section-title"><h2>逐道路预测与误差</h2><button class="button" id="exportPred">↓ 导出当前预测</button></div><div class="card tablewrap" id="predictionTable"></div><div class="pager"><button id="predPrev">上一页</button><span id="predPage"></span><button id="predNext">下一页</button></div>`;['task','feature','model','split'].forEach(id=>$(id).onchange=()=>{predictionPage=0;if(id==='task'&&$('model').value==='MLP'&&D.neuralSelected)$('feature').value=D.neuralSelected[$('task').value].feature_set;updatePredict()})}updatePredict()}
const modelName=x=>({MLP:'多层感知机',linear:'线性回归',random_forest:'随机森林',gradient_boosting:'梯度提升',mean:'均值预测'}[x]||x);
function updatePredict(){const common=D.predictions.filter(r=>r.task===$('task').value&&r.feature_set===$('feature').value&&r.split===$('split').value);predictionRows=common.filter(r=>r.model===$('model').value);const m=calcMetrics(predictionRows);$('predMetrics').innerHTML=[['道路数',m.n],['MAE',num(m.MAE,2)],['RMSE',num(m.RMSE,2)],['R²',num(m.R2,3)]].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('');$('scatter').innerHTML=scatter(predictionRows);$('modelTable').innerHTML=`<table><thead><tr><th>模型</th><th>MAE ↓</th><th>RMSE ↓</th><th>R² ↑</th></tr></thead><tbody>${['mean','linear','random_forest','gradient_boosting','MLP'].map(model=>{const m=calcMetrics(common.filter(r=>r.model===model));return `<tr ${model===$('model').value?'style="background:#eef4e7"':''}><td>${modelName(model)}</td><td>${num(m.MAE,2)}</td><td>${num(m.RMSE,2)}</td><td>${num(m.R2,3)}</td></tr>`}).join('')}</tbody></table>`;const list=predictionRows.slice(predictionPage*25,(predictionPage+1)*25);$('predictionTable').innerHTML=`<table><thead><tr><th>道路</th><th>区域</th><th>实验目标值</th><th>预测值</th><th>绝对误差</th><th>集合</th></tr></thead><tbody>${list.map(r=>{const road=byId.get(r.road_id);return `<tr class="clickable" data-road="${r.road_id}"><td>${esc(road.name||r.road_id)}</td><td>${esc(road.region_group)}</td><td>${num(r.y_true,2)}</td><td>${num(r.y_pred,2)}</td><td>${num(Math.abs(r.y_true-r.y_pred),2)}</td><td>${$('split').selectedOptions[0].text}</td></tr>`}).join('')}</tbody></table>`;$('predPage').textContent=`${predictionRows.length?predictionPage+1:0} / ${Math.ceil(predictionRows.length/25)}`;$('predPrev').disabled=predictionPage===0;$('predNext').disabled=(predictionPage+1)*25>=predictionRows.length}
function scatter(rows){const values=rows.flatMap(r=>[r.y_true,r.y_pred]),lo=Math.min(0,...values),hi=Math.max(100,...values),x=v=>50+(v-lo)/(hi-lo)*450,y=v=>250-(v-lo)/(hi-lo)*215;return `<svg class="scatter" viewBox="0 0 550 300" aria-label="预测散点图">${[0,20,40,60,80,100].map(v=>`<line x1="50" x2="500" y1="${y(v)}" y2="${y(v)}" stroke="#e9eee3"/><text x="39" y="${y(v)+4}" text-anchor="end" font-size="10" fill="#8a9680">${v}</text><text x="${x(v)}" y="270" text-anchor="middle" font-size="10" fill="#8a9680">${v}</text>`).join('')}<line x1="${x(lo)}" y1="${y(lo)}" x2="${x(hi)}" y2="${y(hi)}" stroke="#bbc6ad" stroke-dasharray="5 5"/>${rows.map(r=>`<circle cx="${x(r.y_true)}" cy="${y(r.y_pred)}" r="4" fill="#699477" opacity=".8"><title>${r.road_id} · 目标 ${num(r.y_true)} · 预测 ${num(r.y_pred)}</title></circle>`).join('')}<text x="275" y="294" font-size="10" fill="#7c8c73" text-anchor="middle">实验目标值</text><text transform="translate(14 145) rotate(-90)" font-size="10" fill="#7c8c73" text-anchor="middle">预测值</text></svg>`}
function navigate(){let tab=location.hash.slice(1)||'map';if(!['map','detail','compare','predict'].includes(tab))tab='map';activeTab=tab;const texts={map:['街道地图','从街景，观察街道环境。','连接道路属性、街景视觉特征与预测实验，探索澳门街道的环境差异。'],detail:['街道详情','走近一条街道。','查看道路属性、视觉指标与对应街景图像，了解数据背后的场景。'],compare:['指标对比','并列观察，理解差异。','选择最多四条道路，比较同一尺度下的环境代理指标。'],predict:['预测实验','让实验结果可被检视。','对照基线模型与神经网络，查看误差、目标尺度和逐道路预测。']};const t=texts[tab];$('crumb').textContent=t[0];$('pageTitle').textContent=t[1];$('pageIntro').textContent=t[2];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.tab===tab));for(const n of ['map','detail','compare','predict'])$(n+'-page').hidden=n!==tab;if(tab==='detail')renderDetail();if(tab==='compare')renderCompare();if(tab==='predict')renderPredict();reveal($(tab+'-page'));reveal(document.querySelector('.page-heading'));window.scrollTo(0,0)}
function downloadCSV(name,rows){if(!rows.length)return toast('当前没有可导出的记录');const keys=Object.keys(rows[0]),cell=x=>'"'+String(x??'').replace(/"/g,'""')+'"';const csv='\ufeff'+[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
document.addEventListener('click',e=>{const road=e.target.closest('[data-road]'),add=e.target.closest('[data-add]'),maproad=e.target.closest('[data-maproad]'),remove=e.target.closest('[data-remove]'),photo=e.target.closest('[data-photo]');if(road)selectRoad(road.dataset.road);if(add)addCompare(add.dataset.add);if(maproad&&!dragMoved)selectRoad(maproad.dataset.maproad);if(remove){compared=compared.filter(x=>x!==remove.dataset.remove);renderCompare()}if(photo){const p=D.photoById.get(photo.dataset.photo);modal(`<h2>${p.image_id}</h2><img src="photos/${p.source_sha256}.jpg" alt="街景缩略图 ${p.image_id}"><p>展示用 512 像素缩略图；原始高分辨率照片保留在研究项目中。</p><p>绿化 ${pct(p.vegetation_share)} · 建筑 ${pct(p.building_share)} · 天空 ${pct(p.sky_share)}<br>可见机动车 ${p.motor_vehicle_count} · 可见人物 ${p.person_count}</p><p>质量复核提示：${esc(p.quality_flags||'自动规则未触发；不代表人工验证准确')}</p>`)}if(e.target.id==='prevPhotos'){photoPage--;renderDetail()}if(e.target.id==='nextPhotos'){photoPage++;renderDetail()}if(e.target.id==='compareAdd')addCompare($('compareSelect').value);if(e.target.id==='compareSelected')addCompare(selected);if(e.target.id==='predPrev'){predictionPage--;updatePredict()}if(e.target.id==='predNext'){predictionPage++;updatePredict()}if(e.target.id==='exportPred')downloadCSV('当前预测结果.csv',predictionRows)});
let dragStart=null,dragMoved=false;
function bindMap(){
 const el=$('map');
 el.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(1,Math.min(4,zoom+(e.deltaY<0?.2:-.2)));setMapView();hideMapTooltip()},{passive:false});
 el.addEventListener('pointerdown',e=>{dragStart=[e.clientX,e.clientY,...pan];dragMoved=false});
 window.addEventListener('pointermove',e=>{if(!dragStart)return;const svg=el.querySelector('svg'),matrix=svg?.getScreenCTM();if(!matrix)return;const start=new DOMPoint(dragStart[0],dragStart[1]).matrixTransform(matrix.inverse()),end=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse()),dx=end.x-start.x,dy=end.y-start.y;if(Math.abs(dx)+Math.abs(dy)>5){dragMoved=true;pan=[dragStart[2]+dx,dragStart[3]+dy];setMapView(true);hideMapTooltip()}});
 window.addEventListener('pointerup',()=>{dragStart=null;$('mapViewport')?.classList.remove('is-dragging');setTimeout(()=>dragMoved=false,50)});
 el.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.maproad)selectRoad(e.target.dataset.maproad)});
 el.addEventListener('pointerover',e=>{const circle=e.target.closest('[data-maproad]');if(!circle||dragStart)return;const road=byId.get(circle.dataset.maproad);focusMapRoad(road);showMapTooltip(road,e)});
 el.addEventListener('pointermove',e=>{const circle=e.target.closest('[data-maproad]');if(circle&&!dragStart)showMapTooltip(byId.get(circle.dataset.maproad),e)});
 el.addEventListener('pointerout',e=>{if(e.target.closest('[data-maproad]'))hideMapTooltip()});
 el.addEventListener('pointerleave',hideMapTooltip);
}
function showMapTooltip(road,event){const tooltip=$('mapTooltip');if(!tooltip)return;tooltip.innerHTML=`<b>${esc(road.name||road.road_id)}</b><span>${esc(road.structure_group)} · ${grade(road.fclass)} · ${num(road[metric()])} 分</span>`;tooltip.hidden=false;const rect=$('map').getBoundingClientRect();const left=Math.max(10,Math.min(event.clientX-rect.left+14,rect.width-250));tooltip.style.left=left+'px';tooltip.style.top=Math.max(10,Math.min(event.clientY-rect.top-58,rect.height-75))+'px'}
function hideMapTooltip(){if($('mapTooltip'))$('mapTooltip').hidden=true;focusMapRoad(filtered.find(r=>r.road_id===selected))}

async function init(){try{const embedded=document.getElementById('offline-project-data');if(embedded){D=JSON.parse(embedded.textContent)}else{const response=await fetch('data/project.json');if(!response.ok)throw Error('HTTP '+response.status);D=await response.json();}roads=D.roads;byId=new Map(roads.map(r=>[r.road_id,r]));D.photoById=new Map(D.photos.map(p=>[p.image_id,p]));D.photosByRoad=new Map();for(const p of D.photos){if(!D.photosByRoad.has(p.road_id))D.photosByRoad.set(p.road_id,[]);D.photosByRoad.get(p.road_id).push(p)}for(const [id,key,format] of [['region','region_group',x=>x],['grade','fclass',grade],['structure','structure_group',x=>x]]){const items=[...new Set(roads.map(r=>r[key]))].filter(Boolean);$(id).insertAdjacentHTML('beforeend',items.map(v=>`<option value="${esc(v)}">${esc(format(v))}</option>`).join(''));$(id).onchange=applyFilters}$('search').oninput=applyFilters;$('mapMetric').onchange=()=>{renderMap();renderList()};$('resetFilters').onclick=()=>{for(const id of ['search','region','grade','structure'])$(id).value='';applyFilters()};$('prevRoads').onclick=()=>{roadPage--;renderList()};$('nextRoads').onclick=()=>{roadPage++;renderList()};$('zoomIn').onclick=()=>{zoom=Math.min(4,zoom+.3);setMapView()};$('zoomOut').onclick=()=>{zoom=Math.max(1,zoom-.3);setMapView()};$('zoomReset').onclick=()=>{zoom=1;pan=[0,0];setMapView()};$('download').onclick=()=>downloadCSV('街道环境指标_当前筛选.csv',filtered);selected=roads.find(r=>r.visual_subindex!=null&&r.structure_group==='普通道路').road_id;compared=[selected];$('loading').hidden=true;$('app').hidden=false;applyFilters();bindMap();navigate();window.addEventListener('hashchange',navigate)}catch(e){$('loading').innerHTML='<div>数据载入失败，请刷新重试。<br><small>'+esc(e.message)+'</small></div>';console.error(e)}}
$('modal').querySelector('.modalclose').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').close()};$('methodBtn').onclick=()=>modal(`<h2>指标口径与数据说明</h2><p>本原型用于街道环境质量代理评价。视觉子指数由绿化和低可见车辆标准分构成，完整代理指数再加入低标注限速分。304 条道路有视觉子指数，46 条有完整指数。标准分为相对评价，不是环境达标标准。</p><p>地图与详情展示第一版全样本参考尺度指标。预测实验使用仅在训练集拟合的目标标准化参数，实验目标值与地图指数不能直接混用。</p><p>地图为街景坐标的道路代表位置，边界为研究中沿用的四区域示意判界。原始道路等级按数据字段 primary / secondary / tertiary 展示。</p><p>完整指标覆盖有限；图像识别存在误差。神经网络主种子 42，模型按验证集选择，测试集不参与参数选择。当前页面展示已完成实验结果，未执行在线再训练。</p><p>数据快照：2026-11-08。所有图片为展示用缩略图；全部实际存在的照片记录保留，原本没有照片的采样点不生成缺图标记。</p>`);
const motionQuery=window.matchMedia('(prefers-reduced-motion: reduce)');
let motionPreference=null;try{const stored=localStorage.getItem('street-motion');motionPreference=stored==='on'?true:stored==='off'?false:null}catch{}
function motionAllowed(){return motionPreference===null?!motionQuery.matches:motionPreference}
function reveal(el){if(!el||!motionAllowed())return;for(const a of el.getAnimations())a.cancel();el.animate([{opacity:.25,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:380,easing:'cubic-bezier(.2,.75,.25,1)'})}
function updateMotion(){document.body.dataset.motion=motionAllowed()?'on':'off';const button=$('motionToggle');if(button){button.textContent=motionAllowed()?'动态效果 · 已开启':'动态效果 · 已关闭';button.setAttribute('aria-pressed',String(motionAllowed()))}if(!motionAllowed())for(const a of document.getAnimations())a.cancel()}
const motionButton=document.createElement('button');motionButton.id='motionToggle';motionButton.className='side-button';motionButton.type='button';motionButton.onclick=()=>{motionPreference=!motionAllowed();try{localStorage.setItem('street-motion',motionPreference?'on':'off')}catch{}updateMotion();toast(motionAllowed()?'已开启动效，可随时关闭':'已关闭动态效果')};$('methodBtn').after(motionButton);motionQuery.addEventListener('change',updateMotion);updateMotion();

$('shareSite').onclick=async()=>{if(location.protocol==='file:'){modal('<h2>本地离线版</h2><p>当前网页保存在你的电脑上。远程分享需要先上传到托管平台；现场演示可以直接使用。</p>');return}const url=new URL('.',location.href).href;try{await navigator.clipboard.writeText(url);toast('链接已复制，可粘贴到微信聊天发送')}catch{modal(`<h2>分享网站</h2><p>复制下面的网址，粘贴到微信聊天即可分享。</p><p><a href="${esc(url)}">${esc(url)}</a></p>`)}};
init();
